package com.smartseating.ui;

import com.smartseating.dao.*;
import com.smartseating.model.*;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;

public class TeacherFrame extends AppFrame {
    private final TeacherDAO dao=new TeacherDAO();private final DepartmentDAO deptDAO=new DepartmentDAO();private final JTextField name=new JTextField(),designation=new JTextField(),phone=new JTextField();private final JComboBox<Department> dept=new JComboBox<>();private final JComboBox<String> status=new JComboBox<>(new String[]{"AVAILABLE","UNAVAILABLE"});private final JTable table=new JTable();private Teacher selected;
    public TeacherFrame(User user){super("Teacher / Invigilator Management",user);UI.frame(this,1120,670);build();refresh();}
    private void build(){content.add(title("Teacher / Invigilator Management"),BorderLayout.NORTH);JPanel form=UI.formPanel();UI.addField(form,0,"Name",name);UI.addField(form,1,"Department",dept);UI.addField(form,2,"Designation",designation);UI.addField(form,3,"Phone",phone);UI.addField(form,4,"Status",status);JPanel a=new JPanel(new GridLayout(2,3,7,7));a.setOpaque(false);JButton add=button("ADD",UI.TEAL),update=button("UPDATE",UI.BLUE),del=button("DELETE",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE);for(JButton b:new JButton[]{add,update,del,clear,print})a.add(b);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=5;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);form.add(a,g);content.add(white(form),BorderLayout.WEST);UI.tableStyle(table);content.add(white(UI.scroll(table)),BorderLayout.CENTER);try{for(Department d:deptDAO.findAll())dept.addItem(d);}catch(Exception ex){error(ex);}add.addActionListener(e->save());update.addActionListener(e->update());del.addActionListener(e->delete());clear.addActionListener(e->clear());print.addActionListener(e->PrintService.print("Teacher List",text()));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)load();});if("TEACHER".equals(currentUser.getRole())){add.setEnabled(false);update.setEnabled(false);del.setEnabled(false);}}
    private Teacher read(){Department d=(Department)dept.getSelectedItem();if(d==null)throw new IllegalArgumentException("Department is required.");return new Teacher(0,Validation.text(name.getText(),"Name"),d.getCode(),Validation.text(designation.getText(),"Designation"),Validation.text(phone.getText(),"Phone"),(String)status.getSelectedItem());}private void save(){try{dao.save(read());clear();refresh();}catch(Exception ex){error(ex);}}private void update(){try{if(selected==null)throw new IllegalArgumentException("Select a teacher first.");Teacher t=read();t.setId(selected.getId());dao.update(t);clear();refresh();}catch(Exception ex){error(ex);}}private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select a teacher first.");if(confirm("Delete selected teacher?")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}private void load(){int r=table.getSelectedRow();selected=new Teacher((int)table.getValueAt(r,0),String.valueOf(table.getValueAt(r,1)),String.valueOf(table.getValueAt(r,2)),String.valueOf(table.getValueAt(r,3)),String.valueOf(table.getValueAt(r,4)),String.valueOf(table.getValueAt(r,5)));name.setText(selected.getName());designation.setText(selected.getDesignation());phone.setText(selected.getPhone());status.setSelectedItem(selected.getStatus());for(int i=0;i<dept.getItemCount();i++)if(dept.getItemAt(i).getCode().equals(selected.getDepartmentCode()))dept.setSelectedIndex(i);}private void clear(){selected=null;name.setText("");designation.setText("");phone.setText("");status.setSelectedIndex(0);table.clearSelection();}private void refresh(){try{DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Name","Department","Designation","Phone","Status"},0);for(Teacher t:dao.findAll())m.addRow(new Object[]{t.getId(),t.getName(),t.getDepartmentCode(),t.getDesignation(),t.getPhone(),t.getStatus()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}private String text(){StringBuilder b=new StringBuilder("TEACHER / INVIGILATOR LIST\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,2)).append(" | ").append(table.getValueAt(i,3)).append(" | ").append(table.getValueAt(i,5)).append("\n");return b.toString();}
}
